<template><div><div class="mb-6"><div class="eyebrow mb-2">Lifecycle</div><h1 class="page-heading">Papierkorb</h1><p class="muted mt-2">Gelöschte Rechnungen bleiben 30 Tage wiederherstellbar.</p></div><v-card class="surface-card overflow-hidden"><v-skeleton-loader v-if="loading" type="list-item-two-line@5" /><v-list v-else-if="items.length" lines="two"><v-list-item v-for="invoice in items" :key="invoice.id" class="px-5 py-3"><template #prepend><v-avatar color="error" variant="tonal"><v-icon icon="mdi-delete-clock-outline" /></v-avatar></template><v-list-item-title class="font-weight-bold">{{ invoice.invoiceNumber }} · {{ customer(invoice) }}</v-list-item-title><v-list-item-subtitle>Gelöscht {{ dateTime(invoice.deletedAt) }}<span v-if="invoice.deletedBy"> von {{ invoice.deletedBy.name }}</span> · endgültige Löschung {{ dateTime(invoice.purgeAfter) }}</v-list-item-subtitle><template #append><v-btn color="primary" variant="tonal" prepend-icon="mdi-restore" :loading="restoring===invoice.id" @click="restore(invoice.id)">Wiederherstellen</v-btn></template></v-list-item></v-list><div v-else class="text-center pa-14"><div class="empty-art"><v-icon icon="mdi-delete-empty-outline" size="34" /></div><h2 class="text-h6">Papierkorb ist leer</h2><p class="muted mt-2">Hier erscheinen gelöschte Rechnungen.</p></div><template v-if="items.length"><v-divider/><v-pagination v-model="page" :length="totalPages" class="pa-3" @update:model-value="load" /></template></v-card></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{api,apiMessage}from'../api/client';import{useUiStore}from'../stores/ui';interface TrashInvoice{id:string;invoiceNumber:string;deletedAt:string;purgeAfter:string;deletedBy?:{name:string};customerSnapshot:Record<string,unknown>}const items=ref<TrashInvoice[]>([]),loading=ref(true),restoring=ref(''),page=ref(1),totalPages=ref(1);const ui=useUiStore();async function load(){loading.value=true;try{const r=await api.get('/invoices/trash',{params:{page:page.value}});items.value=r.data.data;totalPages.value=r.data.meta.totalPages;}catch(e){ui.notify(apiMessage(e),'error')}finally{loading.value=false}}async function restore(id:string){restoring.value=id;try{await api.post(`/invoices/${id}/restore`);ui.notify('Rechnung wiederhergestellt.');await load()}catch(e){ui.notify(apiMessage(e),'error')}finally{restoring.value=''}}function customer(i:TrashInvoice){return String(i.customerSnapshot.name??'Unbekannter Kunde')}function dateTime(v:string){return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}onMounted(load);</script>
